impl<'a> TlParser<'a> {
    fn new(b: &'a [u8]) -> TlParser<'a> {
        TlParser { b, p: 0 }
    }

    fn skip_ws(&mut self) {
        while self.p < self.b.len() && matches!(self.b[self.p], b' ' | b'\t' | b'\n' | b'\r') {
            self.p += 1;
        }
    }

    fn peek(&mut self) -> u8 {
        self.skip_ws();
        if self.p >= self.b.len() {
            tl_fail("unexpected end of input");
        }
        self.b[self.p]
    }

    fn expect(&mut self, c: u8) {
        if self.peek() != c {
            tl_fail(&format!("expected `{}`", c as char));
        }
        self.p += 1;
    }

    /// Whether the next non-whitespace byte is `c`, without consuming it -- used to look ahead
    /// for an empty `[]`/`{}` and for the `,` that continues a list.
    fn at(&mut self, c: u8) -> bool {
        self.skip_ws();
        self.p < self.b.len() && self.b[self.p] == c
    }

    fn parse_str(&mut self) -> String {
        self.expect(b'"');
        let mut out = String::new();
        loop {
            if self.p >= self.b.len() {
                tl_fail("unterminated string");
            }
            match self.b[self.p] {
                b'"' => {
                    self.p += 1;
                    break;
                }
                b'\\' => {
                    self.p += 1;
                    if self.p >= self.b.len() {
                        tl_fail("unterminated escape");
                    }
                    out.push(match self.b[self.p] {
                        b'"' => '"',
                        b'\\' => '\\',
                        b'/' => '/',
                        b'n' => '\n',
                        b't' => '\t',
                        b'r' => '\r',
                        b'b' => '\u{8}',
                        b'f' => '\u{c}',
                        _ => tl_fail("unsupported escape"),
                    });
                    self.p += 1;
                }
                c => {
                    // Multi-byte UTF-8 sequences pass through one byte at a time; `push` below
                    // only ever sees a full sequence, since the outer loop keeps consuming until
                    // it does.
                    let start = self.p;
                    self.p += 1;
                    let extra = match c {
                        0x00..=0x7f => 0,
                        0xc0..=0xdf => 1,
                        0xe0..=0xef => 2,
                        0xf0..=0xff => 3,
                        _ => 0,
                    };
                    for _ in 0..extra {
                        if self.p >= self.b.len() {
                            tl_fail("truncated utf-8");
                        }
                        self.p += 1;
                    }
                    out.push_str(std::str::from_utf8(&self.b[start..self.p]).unwrap_or("?"));
                }
            }
        }
        out
    }

    /// Skip one JSON value without interpreting it, for fields the type does not declare.
    fn skip_value(&mut self) {
        match self.peek() {
            b'"' => {
                self.parse_str();
            }
            b'[' | b'{' => {
                let (open, close) = if self.peek() == b'[' { (b'[', b']') } else { (b'{', b'}') };
                let mut depth = 0i32;
                loop {
                    if self.p >= self.b.len() {
                        tl_fail("unterminated value");
                    }
                    if self.b[self.p] == b'"' {
                        self.parse_str();
                        continue;
                    }
                    if self.b[self.p] == open {
                        depth += 1;
                    } else if self.b[self.p] == close {
                        depth -= 1;
                        if depth == 0 {
                            self.p += 1;
                            return;
                        }
                    }
                    self.p += 1;
                }
            }
            _ => {
                while self.p < self.b.len()
                    && !matches!(self.b[self.p], b',' | b'}' | b']')
                {
                    self.p += 1;
                }
            }
        }
    }
}

fn tl_parse_str(p: &mut TlParser) -> String {
    if p.peek() != b'"' {
        tl_fail("expected a string");
    }
    p.parse_str()
}

fn tl_parse_i32(p: &mut TlParser) -> i32 {
    p.skip_ws();
    let start = p.p;
    if p.p < p.b.len() && matches!(p.b[p.p], b'-' | b'+') {
        p.p += 1;
    }
    while p.p < p.b.len() && p.b[p.p].is_ascii_digit() {
        p.p += 1;
    }
    if p.p == start {
        tl_fail("expected an integer");
    }
    if p.p < p.b.len() && matches!(p.b[p.p], b'.' | b'e' | b'E') {
        tl_fail("expected an integer, found a non-integer number");
    }
    let text = std::str::from_utf8(&p.b[start..p.p]).expect("digits and sign are ascii");
    let n: i64 = text.parse().unwrap_or_else(|_| tl_fail("integer is out of range"));
    i32::try_from(n).unwrap_or_else(|_| tl_fail("integer is out of range"))
}

fn tl_parse_f64(p: &mut TlParser) -> f64 {
    p.skip_ws();
    let start = p.p;
    if p.p < p.b.len() && matches!(p.b[p.p], b'-' | b'+') {
        p.p += 1;
    }
    let mut digits = 0;
    while p.p < p.b.len() && p.b[p.p].is_ascii_digit() {
        p.p += 1;
        digits += 1;
    }
    if p.p < p.b.len() && p.b[p.p] == b'.' {
        p.p += 1;
        while p.p < p.b.len() && p.b[p.p].is_ascii_digit() {
            p.p += 1;
            digits += 1;
        }
    }
    if digits == 0 {
        tl_fail("expected a number");
    }
    if p.p < p.b.len() && matches!(p.b[p.p], b'e' | b'E') {
        p.p += 1;
        if p.p < p.b.len() && matches!(p.b[p.p], b'-' | b'+') {
            p.p += 1;
        }
        if p.p >= p.b.len() || !p.b[p.p].is_ascii_digit() {
            tl_fail("malformed exponent");
        }
        while p.p < p.b.len() && p.b[p.p].is_ascii_digit() {
            p.p += 1;
        }
    }
    let text = std::str::from_utf8(&p.b[start..p.p]).expect("number characters are ascii");
    text.parse().unwrap_or_else(|_| tl_fail("number is out of range"))
}

fn tl_parse_bool(p: &mut TlParser) -> bool {
    p.skip_ws();
    if p.b[p.p..].starts_with(b"true") {
        p.p += 4;
        true
    } else if p.b[p.p..].starts_with(b"false") {
        p.p += 5;
        false
    } else {
        tl_fail("expected a boolean")
    }
}

fn tl_parse_vec<T>(p: &mut TlParser, elem: fn(&mut TlParser) -> T) -> Vec<T> {
    p.expect(b'[');
    let mut out = Vec::new();
    if p.at(b']') {
        p.p += 1;
        return out;
    }
    loop {
        out.push(elem(p));
        if p.at(b',') {
            p.p += 1;
            continue;
        }
        break;
    }
    p.expect(b']');
    out
}

/// Reads a value from one already-owned line of text, refusing anything left over -- the same
/// "trailing content after the value" check `tl_read_value` uses for a whole document, applied
/// per line since `inputs` is many documents, not one.
fn tl_parse_line<T>(line: &str, elem: fn(&mut TlParser) -> T) -> T {
    let mut p = TlParser::new(line.as_bytes());
    let v = elem(&mut p);
    if p.at(b'\0') || p.p != p.b.len() {
        p.skip_ws();
        if p.p != p.b.len() {
            tl_fail("trailing content after the value");
        }
    }
    v
}

fn tl_read_value<T>(elem: fn(&mut TlParser) -> T) -> T {
    let bytes = tl_read_all_stdin();
    let mut p = TlParser::new(&bytes);
    let v = elem(&mut p);
    p.skip_ws();
    if p.p != p.b.len() {
        tl_fail("trailing content after the value");
    }
    v
}

fn tl_read_values<T>(elem: fn(&mut TlParser) -> T) -> Vec<T> {
    tl_read_lines()
        .into_iter()
        .filter(|l| !l.trim().is_empty())
        .map(|l| tl_parse_line(&l, elem))
        .collect()
}

fn tl_quote(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c == '\u{7f}' => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn tl_jsonlines<T>(v: &[T], f: fn(&T) -> String) -> String {
    let parts: Vec<String> = v.iter().map(f).collect();
    parts.join("\n")
}

#[derive(Clone, PartialEq)]
struct TlRec0 {
    f_body: String,
}

fn tl_parse_rec0(p: &mut TlParser) -> TlRec0 {
    let mut f_body: Option<String> = None;
    p.expect(b'{');
    if !p.at(b'}') {
        loop {
            let key = tl_parse_str(p);
            p.expect(b':');
            match key.as_str() {
                "body" => f_body = Some((tl_parse_str)(p)),
                _ => p.skip_value(),
            }
            if p.at(b',') { p.p += 1; continue; }
            break;
        }
    }
    p.expect(b'}');
    TlRec0 {
        f_body: f_body.unwrap_or_else(|| tl_fail("missing field `body`")),
    }
}

#[derive(Clone, PartialEq)]
#[allow(non_camel_case_types)]
enum TlE_Msg {
    V_Ping,
    V_Text(TlRec0),
}

fn tl_parse_enum0(p: &mut TlParser) -> TlE_Msg {
    if p.peek() == b'"' {
        let s = p.parse_str();
        match s.as_str() {
            "Ping" => TlE_Msg::V_Ping,
            _ => tl_fail(&format!("`{s}` is not a unit variant of Msg")),
        }
    } else {
        p.expect(b'{');
        let key = tl_parse_str(p);
        p.expect(b':');
        let v = match key.as_str() {
            "Text" => TlE_Msg::V_Text((tl_parse_rec0)(p)),
            _ => tl_fail(&format!("`{key}` is not a payload variant of Msg")),
        };
        p.expect(b'}');
        v
    }
}

fn v_render(v_msgs: Vec<TlE_Msg>) -> Vec<String> {
    ({ let t_0: Vec<TlE_Msg> = v_msgs.clone(); t_0.clone().iter().map(|t_1: &TlE_Msg| -> String { ({ let t_2: TlE_Msg = t_1.clone(); (match t_2.clone() { TlE_Msg::V_Text(t_3) => t_3.clone().f_body, _ => "*ping*".to_string() }) }) }).collect::<Vec<_>>() })
}

fn main() {
    use std::io::{BufRead, Write};
    let stdout = std::io::stdout();
    let mut stdout = stdout.lock();
    let stdin = std::io::stdin();
    let mut stdin = stdin.lock();
    let mut line = String::new();
    loop {
        line.clear();
        let n = stdin.read_line(&mut line).unwrap_or_else(|e| tl_fail(&format!("could not read stdin: {e}")));
        if n == 0 { break; }
        if line.ends_with('\n') { line.pop(); }
        if line.trim().is_empty() { continue; }
        let t_line: TlE_Msg = tl_parse_line(&line, tl_parse_enum0);
        let t_1: TlE_Msg = t_line;
        writeln!(stdout, "{}", tl_quote(&({ let t_2: TlE_Msg = t_1.clone(); (match t_2.clone() { TlE_Msg::V_Text(t_3) => t_3.clone().f_body, _ => "*ping*".to_string() }) }))).unwrap();
        stdout.flush().unwrap();
    }
}

