fn insert_each({ x, p }: { x: Int, p: Vec<Int> }) -> Vec<Vec<Int>> =
  p
  | length(p) == 0 -> [[x]] or
    [[x] + p] +
      (insert_each { x: x, p: tail(p)! } | map([p[0]!] + .));


fn build_perms(
  { x, ps }: { x: Int, ps: Vec<Vec<Int>> }
) -> Vec<Vec<Int>> =
  ps
  | length(ps) == 0 -> [] or
    insert_each { x: x, p: ps[0]! } +
      build_perms { x: x, ps: tail(ps)! };


fn perms(v: Vec<Int>) -> Vec<Vec<Int>> =
  v
  | length(v) == 0 -> [[]] or
    build_perms { x: v[0]!, ps: perms tail(v)! };


fn flips(p: Vec<Int>) -> Int =
  p | p[0]! == 1 -> 0 or 1 + flips(reverse p[:p[0]!] + p[p[0]!:]);


fn invs(p: Vec<Int>) -> Int =
  p
  | length(p) <= 1 -> 0 or
    (length(tail(p)! | select(. < p[0]!)) + invs(tail(p)!)) % 2;


fn fk_step(
  { p, acc }: { p: Vec<Int>, acc: { checksum: Int, max: Int } }
) -> { checksum: Int, max: Int } =
  let f = flips p

  {
    checksum: acc.checksum + (invs(p) == 0 | . -> f or 0 - f),
    max: f > acc.max | . -> f or acc.max
  };


fn fold(
  { v, acc }: { v: Vec<Vec<Int>>, acc: { checksum: Int, max: Int } }
) -> { checksum: Int, max: Int } =
  v
  | length(v) == 0 -> acc or
    fold { v: tail(v)!, acc: fk_step { p: v[0]!, acc: acc } };


fn fk(n: Int) -> Str =
  let r = fold { v: perms(collect(range n) | map(. + 1)), acc: { checksum: 0, max: 0 } }

  str(r.checksum) + "\nPfannkuchen(" + str(n) + ") = " + str(r.max);


