fn tl_at<T: Clone>(v: &[T], i: i32) -> Option<T> {
    let n = v.len() as i32;
    let i = if i < 0 { n + i } else { i };
    if i < 0 || i >= n {
        None
    } else {
        Some(v[i as usize].clone())
    }
}

fn tl_unwrap<T>(o: Option<T>) -> T {
