fn to_float(n: Int) -> Float =
  n | . == 0 -> 0.0 or 1.0 + to_float(. - 1);


fn pixel(
  { cr, ci, zr, zi, k }: {
    cr: Float,
    ci: Float,
    zr: Float,
    zi: Float,
    k: Int
  }
) -> Str =
  k
  | . == 0 -> "1" or
    zr * zr + zi * zi > 4.0 -> "0" or
    pixel {
      cr: cr,
      ci: ci,
      zr: zr * zr - zi * zi + cr,
      zi: 2.0 * zr * zi + ci,
      k: . - 1
    };


fn row(
  { n, size, x, fx, ci, line }: {
    n: Int,
    size: Float,
    x: Int,
    fx: Float,
    ci: Float,
    line: Str
  }
) -> Str =
  n
  | x == n -> line or
    row {
      n: n,
      size: size,
      x: x + 1,
      fx: fx + 1.0,
      ci: ci,
      line: line +
        pixel {
          cr: 2.0 * fx / size - 1.5,
          ci: ci,
          zr: 0.0,
          zi: 0.0,
          k: 50
        }
    };


