  { n, size, y, fy, lines }: {
    n: Int,
    size: Float,
    y: Int,
    fy: Float,
    lines: Vec<Str>
  }
) -> Vec<Str> =
  n
  | y == n -> lines or
    rows {
      n: n,
      size: size,
      y: y + 1,
      fy: fy + 1.0,
      lines: lines +
        [
          row {
            n: n,
            size: size,
            x: 0,
            fx: 0.0,
            ci: 2.0 * fy / size - 1.0,
            line: ""
          }
        ]
    };


