    fn new(b: &'a [u8]) -> TlParser<'a> {
        TlParser { b, p: 0 }
    }

    fn skip_ws(&mut self) {
        while self.p < self.b.len() && matches!(self.b[self.p], b' ' | b'\t' | b'\n' | b'\r') {
            self.p += 1;
        }
    }

    fn peek(&mut self) -> u8 {
        self.skip_ws();
        if self.p >= self.b.len() {
            tl_fail("unexpected end of input");
        }
        self.b[self.p]
    }

    fn expect(&mut self, c: u8) {
        if self.peek() != c {
            tl_fail(&format!("expected `{}`", c as char));
